      rule_scapular_push_up: "الكوعان مفرودان ومثبتان طوال المجموعة؛ عزل تام لحركة تباعد وتقارب لوحي الكتف فقط.",
      rule_scapular_pull_up: "تعليق نشط، سحب لوحي الكتف للأسفل والخلف دون ثني الكوعين، توقف لثانية بتحكم.",
      rule_dead_hang: "قبضة محكمة على البار، تنفس هادئ من الحجاب الحاجز، استرخاء محكوم للعمود الفقري دون تأرجح.",
      rule_high_knees: "رفع الركبتين لمستوى الخصر بإيقاع ثابت، هبوط سلس على مشط القدمين مع قوام مستقيم.",
      rule_band_pull_apart: "انحناء خفيف وثابت في الكوعين، سحب الشريط لمنتصف الصدر مع عصر لوحي الكتف معاً.",
      rule_seated_band_row: "ظهر مستقيم، صدر مرتفع، سحب الكوعين بمحاذاة القفص الصدري لأسفل البطن مع شد كامل لعضلات الظهر.",
      rule_bodyweight_squat: "نزول محكوم لعمق كامل (الفخذان بمستوى موازٍ للأرض)، الركبتان باتجاه أصابع القدمين وصدر مرتفع.",
      rule_glute_bridge: "دفع قوي من خلال الكعبين، شد قوي لعضلات المؤخرة عند القمة، خط مستقيم من الركبتين حتى الكتفين.",
      rule_dead_bug: "إبقاء أسفل الظهر ملتصقاً تماماً بالأرض، نزول بطيء ومتناسق لليد والرجل المتعاكستين.",
      rule_relaxed_walking: "مشي خفيف للاستشفاء (4.5 كم/س)، تنفس أنفي هادئ لخفض التوتر وتسريع التعافي.",
      rule_brisk_walking: "مشي سريع ومستمر لبناء قاعدة هوائية عند نبض المنطقة 2 (60-70% أقصى نبض (112-131 BPM)، اختبار الكلام بسلاسة). أساس استرشادي: 5.5 كم/س مع ميل 4% — عدل السرعة والميل للبقاء في نطاق النبض الشخصي.",
      rule_single_arm_seated_ohp: "جلوس مستقيم، شد عضلات الجذع، ضغط عمودي محكم فوق الكتف دون أي ميل للجذع.",
      rule_push_up_progression: "جسم مشدود كلوح مستقيم، مدى حركة كامل مع ملامسة المقابض بالصدر، وفرد محكوم بالأعلى.",
      rule_trx_row: "استقامة كاملة للجسم، سحب الصدر نحو المقابض بقيادة الكوعين، وعصر لوحي الكتف عند القمة.",
      rule_trx_ytw: "تحكم كامل بلوحي الكتف، حركة سلسة في أنماط Y وT وW دون اندفاع بالجسم.",
