      rule_one_arm_db_row: "ظهر مستقيم موازٍ، سحب الدامبل نحو الخصر مع شد أقصى لعضلات الظهر الجانبية دون دوران للجذع.",
      rule_tuck_l_sit: "دفع قوي للأرض للأسفل، تقريب الركبتين للصدر، وتنفس ثابت مع ثبات تام.",
      rule_micro_mobility_protocol: "تدفق سلس بين التمارين، التركيز على تشحيم المفاصل وتحرير الرقبة والكتفين والحوض.",
      rule_deep_mobility_protocol: "ثبات محكوم عند توتر مريح، تنفس عميق وزيادة تدريجية في مدى الحركة دون ألم.",
      rule_wall_sit: "الظهر مسطح تماماً على الحائط، الفخذان موازيان للأرض بزاوية 90 درجة (أو 60-70 درجة لراحة الركبة)، الساقان عموديتان، وتنفس حجابي مستمر.",
